SELECT COUNT(customer_id) AS customer_count
FROM gold.gold_top_customers
WHERE region = 'EUROPE';

SELECT COUNT(supplier_id) 
FROM gold.gold_supplier_performance 
WHERE avg_delay_days > 0;

SELECT SUM(revenue) AS total_revenue_1995
FROM gold.gold_monthly_sales
WHERE month >= '1995-01-01' AND month < '1996-01-01';

SELECT COUNT(customer_id) AS customer_count
FROM gold.gold_top_customers
WHERE region = 'EUROPE';

SELECT region, SUM(revenue) AS total_revenue
FROM gold.gold_top_customers
GROUP BY region;

SELECT COUNT(supplier_id) AS num_suppliers_with_positive_delay
FROM gold.gold_supplier_performance
WHERE avg_delay_days > 0;
